-- 2) Contenido (una entrada, si no existe)
INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, orden, migrado_de)
SELECT p.id, 'Programa de Transparencia y Ética Empresarial (PTEE)', 'etica-y-transparencia-ptee', 'Integridad, transparencia y lucha contra la corrupción en la E.S.E. Hospital San José del Guaviare.',
  '<h2>Programa de Transparencia y Ética Empresarial</h2><p>La E.S.E. Hospital San José del Guaviare promueve una cultura de integridad, transparencia y legalidad en todas sus actuaciones. El Programa de Transparencia y Ética Empresarial (PTEE) reúne las políticas, los principios y los mecanismos con los que la entidad previene la corrupción y fortalece la confianza de la ciudadanía.</p><h3>¿Qué es el PTEE?</h3><p><em>El compromiso institucional con la integridad y la lucha contra la corrupción.</em></p><p>Es el conjunto de políticas, procedimientos y controles orientados a prevenir y gestionar los riesgos de corrupción, fraude y faltas a la ética, en el marco del Modelo Integrado de Planeación y Gestión (MIPG) y de la normatividad nacional:</p><ul><li><strong>Ley 2195 de 2022:</strong> transparencia, prevención y lucha contra la corrupción.</li><li><strong>Ley 1474 de 2011:</strong> Estatuto Anticorrupción.</li><li><strong>Decreto 1499 de 2017 (MIPG):</strong> política de Integridad y dimensión de Control Interno.</li><li><strong>Ley 1712 de 2012:</strong> transparencia y acceso a la información pública.</li></ul><h3>Código de Integridad</h3><p><em>Los valores que guían el servicio público en la E.S.E.</em></p><p>Los servidores de la entidad actúan conforme a los cinco valores del Código de Integridad del servicio público colombiano:</p><ul><li><strong>Honestidad:</strong> actúo con fundamento en la verdad, con transparencia y rectitud, favoreciendo el interés general.</li><li><strong>Respeto:</strong> reconozco, valoro y trato de manera digna a todas las personas, sin discriminación.</li><li><strong>Compromiso:</strong> soy consciente de mi rol como servidor público y me dispongo a atender las necesidades de la ciudadanía.</li><li><strong>Diligencia:</strong> cumplo mis deberes y funciones de la mejor manera, optimizando el uso de los recursos públicos.</li><li><strong>Justicia:</strong> actúo con imparcialidad, equidad e igualdad, garantizando los derechos de las personas.</li></ul><h3>Canal de denuncias</h3><p><em>Reporta hechos de corrupción de manera reservada.</em></p><p>Cualquier persona puede reportar posibles hechos de corrupción, fraude o faltas a la ética. El Oficial de Cumplimiento revisa cada reporte de forma confidencial.</p><ul><li><a href="/sicof">Canal anticorrupción SICOF</a></li><li><a href="/pqrsf">PQRSFD — denuncias</a></li></ul><h3>Conflictos de interés</h3><p><em>Transparencia en las decisiones y en la declaración de bienes e intereses.</em></p><p>En cumplimiento de la Ley 2013 de 2019, los servidores públicos declaran sus bienes, rentas y conflictos de interés. Su adecuada gestión evita que intereses particulares afecten las decisiones institucionales.</p><ul><li><a href="https://www.funcionpublica.gov.co/web/sigep2" target="_blank" rel="noopener">Declaración de bienes, rentas y conflictos de interés (SIGEP II)</a></li></ul><h3>Gestión del riesgo de corrupción</h3><p><em>Identificación, seguimiento y control de los riesgos de corrupción.</em></p><p>La E.S.E. identifica y monitorea sus riesgos de corrupción en el mapa de riesgos institucional, que hace parte del Plan Anticorrupción y de Atención al Ciudadano, y rinde cuentas a la ciudadanía sobre su gestión.</p><ul><li><a href="/plan-anticorrupcion-y-de-atencion-al-ciudadano">Plan Anticorrupción y de Atención al Ciudadano (PAAC)</a></li><li><a href="/rendicion-de-cuentas">Rendición de cuentas</a></li><li><a href="/participacion">Participación ciudadana y control social</a></li></ul><h3>¿Quieres reportar un hecho de corrupción?</h3><p>Usa el canal SICOF: tu reporte es reservado y lo revisa el Oficial de Cumplimiento.</p><p><a href="/sicof">Ir al canal de denuncias</a></p>',
  'articulo', 'Transparencia', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', '2026-11-09 12:00:00', 0, 'Cumplimiento PTEE / MIPG — Ética y transparencia'
  FROM cms_paginas p WHERE p.slug = 'etica-y-transparencia'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas x JOIN cms_paginas q ON q.id = x.pagina_id WHERE q.slug = 'etica-y-transparencia' AND x.slug = 'etica-y-transparencia-ptee');
